public final class NativeSmokeTest extends Instrumentation {
    private File output;private StringBuilder log=new StringBuilder();
    public void onCreate(Bundle b){super.onCreate(b);start();}
    private void line(String message)throws Exception{log.append(message).append('\n');File file=new File(output,"results.txt");try(OutputStream out=new FileOutputStream(file)){out.write(log.toString().getBytes("UTF-8"));}upload(file);}
    private void upload(File file){android.util.Log.i("ReviewQA",file.getAbsolutePath());}
    private void check(boolean ok,String message)throws Exception{if(!ok)throw new AssertionError(message);line("PASS "+message);}
    @Override public void onStart(){output=new File(getTargetContext().getExternalFilesDir(null),"qa");output.mkdirs();Bundle result=new Bundle();int code=Activity.RESULT_OK;try{runTests();line("ALL PASSED");}catch(Throwable e){code=Activity.RESULT_CANCELED;try{StringWriter trace=new StringWriter();e.printStackTrace(new PrintWriter(trace));line("FAIL "+trace);}catch(Exception ignored){android.util.Log.e("ReviewQA","Could not write test log",e);}}result.putString("stream",log.toString());finish(code,result);}
    private Activity open(Class<?> cls,long id){Intent intent=new Intent(getTargetContext(),cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(id!=0)intent.putExtra("taskId",id);Activity a=startActivitySync(intent);waitForIdleSync();return a;}
    private View find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().startsWith(text))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View hit=find(g.getChildAt(i),text);if(hit!=null)return hit;}}return null;}
    private View findDescription(View v,String text){if(text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View hit=findDescription(g.getChildAt(i),text);if(hit!=null)return hit;}}return null;}
    private void click(Activity a,String text)throws Exception{final Throwable[] error={null};runOnMainSync(()->{try{View v=find(a.getWindow().getDecorView(),text);if(v==null)throw new AssertionError("Missing "+text);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();v.performClick();}catch(Throwable t){error[0]=t;}});waitForIdleSync();Thread.sleep(230);if(error[0]!=null)throw new Exception(error[0]);}
    private void call(Activity a,String method)throws Exception{final Throwable[] error={null};runOnMainSync(()->{try{Method m=a.getClass().getDeclaredMethod(method);m.setAccessible(true);m.invoke(a);}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new Exception(error[0]);}
    private void screenshot(Activity a,String name,int width,int height)throws Exception{runOnMainSync(()->{View root=a.getWindow().getDecorView().findViewById(android.R.id.content);float d=a.getResources().getDisplayMetrics().density;int w=(int)(width*d),h=(int)(height*d);root.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));root.layout(0,0,w,h);Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);root.draw(new Canvas(b));try(FileOutputStream out=new FileOutputStream(new File(output,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new RuntimeException(e);}b.recycle();});upload(new File(output,name+".png"));line("SCREENSHOT "+name);}
    private void runTests()throws Exception{
        line("START native QA "+android.os.Build.VERSION.RELEASE);Store.prefs(getTargetContext()).edit().clear().commit();Store.prefs(getTargetContext()).edit().putBoolean("motion",false).putBoolean("setupComplete",true).putString("extraIntervals","43200,86400").putString("windows","07:30-08:30,22:00-01:00").putBoolean("respectWindows",true).apply();check(Store.windows("07:30-08:30,22:00-01:00").size()==2,"multiple and overnight windows parse");check(Store.windows("").isEmpty(),"empty windows mean all day");check(ReminderWindows.active(getTargetContext()).equals("07:30-08:30,22:00-01:00"),"enabled window restriction is active");Store.prefs(getTargetContext()).edit().putBoolean("respectWindows",false).commit();check(ReminderWindows.active(getTargetContext()).isEmpty(),"disabled restriction means all day");Store.prefs(getTargetContext()).edit().putBoolean("respectWindows",true).commit();Words.clearDraft(getTargetContext());
        Words.lesson(getTargetContext());JSONObject draft=Words.draft(getTargetContext());check(draft.getJSONArray("words").length()==42,"Lesson 1 has 42 cards");
        Bitmap sample=Bitmap.createBitmap(1100,220,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(sample);canvas.drawColor(Color.WHITE);Paint paint=new Paint(3);paint.setColor(Color.BLACK);paint.setTextSize(70);canvas.drawText("ambition",35,100,paint);canvas.drawText("conquer",35,185,paint);String raw=Ocr.recognize(getTargetContext(),sample);sample.recycle();check(raw.toLowerCase().contains("ambition")&&raw.toLowerCase().contains("conquer"),"Android native OCR loads and reads text");
        for(int i=1;i<=2;i++){File f=new File(draft.getJSONArray("photos").getString(i-1));Bitmap page=Ocr.decode(f);String actual=Ocr.recognize(getTargetContext(),page);page.recycle();File rawFile=new File(output,"page"+i+"-ocr.txt");try(OutputStream out=new FileOutputStream(rawFile)){out.write(actual.getBytes("UTF-8"));}upload(rawFile);check(!actual.trim().isEmpty(),"OCR on original Lesson 1 page "+i);}
        Store.prefs(getTargetContext()).edit().putBoolean("setupComplete",false).commit();Activity main=open(MainActivity.class,0);Object setup=field(main,"setupDialog");check(((android.app.AlertDialog)setup).isShowing(),"first-run setup wizard opens");call(main,"advanceSetup");check(intField(main,"setupStep")==1,"setup advances to out-of-window rule");call(main,"advanceSetup");check(intField(main,"setupStep")==2,"setup advances to permission guidance");call(main,"advanceSetup");check(Store.prefs(getTargetContext()).getBoolean("setupComplete",false),"setup wizard saves selected preferences");screenshot(main,"home-360",360,760);click(main,"我的");check(!find(main.getWindow().getDecorView(),"第一次复习").isShown(),"base intervals initially collapsed");check(find(main.getWindow().getDecorView(),"添加提醒时间段")!=null,"settings use selectable time-window rows");check(find(main.getWindow().getDecorView(),"只在选择的时段内提醒")!=null,"time-window restriction has an explicit toggle");final TimeWindowPicker[] picker={null};runOnMainSync(()->{picker[0]=new TimeWindowPicker(main,"",null);View add=find(picker[0].view(),"添加提醒时间段");add.performClick();add.performClick();});check(picker[0].draftValue().equals("09:00-10:00,09:00-10:00"),"time picker adds multiple editable windows");screenshot(main,"settings-collapsed-360",360,760);click(main,"自定义间隔");screenshot(main,"settings-expanded-360",360,860);runOnMainSync(()->main.finish());
        JSONObject quickDraft=new JSONObject().put("title","快速校对测试").put("words",new JSONArray().put(new JSONObject().put("english","hello").put("chinese","你好").put("example","")).put(new JSONObject().put("english","world").put("chinese","世界").put("example",""))).put("photos",new JSONArray());Words.writeDraft(getTargetContext(),quickDraft);
        Intent quickIntent=new Intent(getTargetContext(),WordEditorActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("quickReview",true);Activity quick=startActivitySync(quickIntent);waitForIdleSync();check(find(quick.getWindow().getDecorView(),"hello")!=null&&find(quick.getWindow().getDecorView(),"你好")!=null,"quick proofreading opens a read-only vocabulary card");screenshot(quick,"proof-quick-360",360,760);click(quick,"有问题，修改");check(find(quick.getWindow().getDecorView(),"保存并返回确认")!=null,"problem action opens the card editor");runOnMainSync(()->{try{Field f=WordEditorActivity.class.getDeclaredField("chinese");f.setAccessible(true);((EditText)f.get(quick)).setText("你好（修正）");}catch(Exception e){throw new RuntimeException(e);}});click(quick,"保存并返回确认");check(find(quick.getWindow().getDecorView(),"你好（修正）")!=null,"saving correction returns to the same confirmation card");click(quick,"没问题，下一张");check(find(quick.getWindow().getDecorView(),"world")!=null,"confirm action advances to the next card");runOnMainSync(()->quick.finish());Words.lesson(getTargetContext());
        Activity editor=open(WordEditorActivity.class,0);screenshot(editor,"editor-360",360,860);runOnMainSync(()->{try{Field f=WordEditorActivity.class.getDeclaredField("chinese");f.setAccessible(true);((EditText)f.get(editor)).setText("n. 野心；雄心；抱负（已校对）");}catch(Exception e){throw new RuntimeException(e);}});click(editor,"下一张");check(Words.draft(getTargetContext()).getJSONArray("words").getJSONObject(0).getString("chinese").contains("已校对"),"editing card persists on next");call(editor,"commit");waitForIdleSync();
        JSONArray all=Store.tasks(getTargetContext());check(all.length()==1,"word group becomes a task");JSONObject task=all.getJSONObject(0);check(task.getJSONArray("intervals").length()==9,"custom intervals appended to task snapshot");check(task.getString("windows").equals("07:30-08:30,22:00-01:00"),"word task snapshots enabled time windows");check(!new File(getTargetContext().getFilesDir(),"word-draft.json").exists(),"committed draft cleared");
        long id=task.getLong("id");Activity review=open(ReviewActivity.class,id);screenshot(review,"review-front-360",360,760);check(find(review.getWindow().getDecorView(),"记得")==null,"feedback hidden before reveal");click(review,"显示答案");screenshot(review,"review-answer-360",360,760);click(review,"再看一次");check(Store.find(Store.tasks(getTargetContext()),id).getInt("stage")==0,"card answer does not advance stage");
        int guard=0;while(find(review.getWindow().getDecorView(),"本轮已看完")==null&&guard++<60){click(review,"显示答案");click(review,"记得");}check(guard<60,"review queue terminates after retry");screenshot(review,"review-summary-360",360,760);call(review,"complete");check(Store.find(Store.tasks(getTargetContext()),id).getInt("stage")==1,"explicit completion advances exactly one stage");
        call(review,"complete");check(Store.find(Store.tasks(getTargetContext()),id).getInt("stage")==1,"duplicate completion does not advance stage");testCalendarAndFeedback(id);
        Store.prefs(getTargetContext()).edit().putBoolean("motion",true).commit();Activity wide=open(MainActivity.class,0);Thread.sleep(250);check(Motion.enabled(wide),"animations enabled in native runtime");screenshot(wide,"home-800",800,760);click(wide,"我的");click(wide,"默认间隔");Thread.sleep(200);check(find(wide.getWindow().getDecorView(),"第一次复习").isShown(),"animated interval expansion finishes");click(wide,"默认间隔");Thread.sleep(200);check(!find(wide.getWindow().getDecorView(),"第一次复习").isShown(),"animated interval collapse finishes");
        click(wide,"主页");Activity animated=open(ReviewActivity.class,id);click(animated,"显示答案");click(animated,"记得");check(find(animated.getWindow().getDecorView(),"2 / ")!=null,"animated answer advances one card");screenshot(animated,"review-motion-360",360,760);runOnMainSync(()->animated.finish());runOnMainSync(()->wide.finish());
        Activity imported=open(ImportActivity.class,0);runOnMainSync(()->{try{Field f=ImportActivity.class.getDeclaredField("currentPhoto");f.setAccessible(true);f.set(imported,new File(draft.getJSONArray("photos").getString(0)));Method m=ImportActivity.class.getDeclaredMethod("result",String.class,String.class);m.setAccessible(true);m.invoke(imported,"ambition 野心",draft.getJSONArray("photos").getString(0));Field source=ImportActivity.class.getDeclaredField("recognized");source.setAccessible(true);((EditText)source.get(imported)).setText("ambition 雄心 已修正");}catch(Exception e){throw new RuntimeException(e);}});ActivityMonitor monitor=addMonitor(ImportActivity.class.getName(),null,false);runOnMainSync(()->imported.recreate());Activity restored=monitor.waitForActivityWithTimeout(5000);check(restored!=null,"OCR result activity recreated");waitForIdleSync();check(find(restored.getWindow().getDecorView(),"ambition 雄心 已修正")!=null,"edited OCR text survives recreation");screenshot(restored,"import-result-360",360,760);removeMonitor(monitor);runOnMainSync(()->restored.finish());
    }
    private void testCalendarAndFeedback(long id)throws Exception{
        Store.prefs(getTargetContext()).edit().putBoolean("motion",false).putInt("reviewMode",1).putBoolean("autoSpeak",true).commit();
        Activity review=open(ReviewActivity.class,id);Thread.sleep(700);boolean[] loaded=(boolean[])field(field(review,"interaction"),"loaded");check(loaded[0]&&loaded[1]&&loaded[2],"custom feedback sounds load");check(field(review,"tts")==null,"Chinese-first card does not reveal the answer through speech");check(!find(review.getWindow().getDecorView(),"朗读单词").isShown(),"manual pronunciation hidden until English revealed");click(review,"显示答案");check(find(review.getWindow().getDecorView(),"朗读单词").isShown(),"manual pronunciation available after reveal");runOnMainSync(()->review.finish());
        Store.prefs(getTargetContext()).edit().putInt("reviewMode",0).commit();Activity main=open(MainActivity.class,0);check(find(main.getWindow().getDecorView(),"已完成的任务")!=null,"completed tasks section is on home");click(main,"已完成的任务");check(find(main.getWindow().getDecorView(),"今天完成")==null,"completed section collapses");click(main,"已完成的任务");check(find(main.getWindow().getDecorView(),"今天完成")!=null,"completed section defaults to today");click(main,"日历");check(find(main.getWindow().getDecorView(),"完成第 1 轮")!=null,"calendar shows actual review history");screenshot(main,"calendar-360",360,760);
        java.util.Calendar c=java.util.Calendar.getInstance();c.set(java.util.Calendar.DAY_OF_MONTH,1);c.add(java.util.Calendar.MONTH,1);String next=new java.text.SimpleDateFormat("yyyy年M月d日",java.util.Locale.CHINA).format(c.getTime());runOnMainSync(()->findDescription(main.getWindow().getDecorView(),"下个月").performClick());waitForIdleSync();check(findDescription(main.getWindow().getDecorView(),next)!=null,"calendar displays all dates in the next month");runOnMainSync(()->findDescription(main.getWindow().getDecorView(),next).performClick());check(find(main.getWindow().getDecorView(),"当天没有计划或完成记录")!=null,"selecting another date updates its events");
        click(main,"我的");check(find(main.getWindow().getDecorView(),"复习统计")!=null,"statistics shown on profile");check(find(main.getWindow().getDecorView(),"完成 1 轮")!=null,"heatmap counts actual completed review rounds");check(find(main.getWindow().getDecorView(),"朗读声音与语速")!=null,"speech settings entry available");check(SpeechSettings.rate(2)==0.85f&&SpeechSettings.rate(-1)==0.60f&&SpeechSettings.rate(99)==1.15f,"speech rates and bounds");testSpeechSettings(main);screenshot(main,"profile-360",360,760);click(main,"试听：记得");click(main,"试听：再看一次");check(find(main.getWindow().getDecorView(),"复习确认音效")!=null,"custom sound previews and setting available");Switch sound=(Switch)find(main.getWindow().getDecorView(),"到期通知使用声音");runOnMainSync(()->sound.setChecked(false));click(main,"保存设置");check(!Store.prefs(getTargetContext()).getBoolean("reminderSound",true),"notification sound preference saved");check(Notifications.channel(getTargetContext()).equals("reviews_silent"),"silent channel selected");runOnMainSync(()->main.finish());
    }
    private void testSpeechSettings(Activity main)throws Exception{
        final Object[] settings=new Object[1];Constructor<SpeechSettings> constructor=SpeechSettings.class.getDeclaredConstructor(Activity.class);constructor.setAccessible(true);
        runOnMainSync(()->{try{settings[0]=constructor.newInstance(main);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
        AlertDialog dialog=(AlertDialog)field(settings[0],"dialog");Spinner rate=(Spinner)field(settings[0],"rate");check(dialog.isShowing()&&rate.getCount()==5,"speech dialog exposes five rates");
        runOnMainSync(()->{rate.setSelection(1);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();});check(Store.prefs(getTargetContext()).getInt("speechRate",2)==2,"cancel does not save speech rate");
        runOnMainSync(()->{try{settings[0]=constructor.newInstance(main);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
        AlertDialog saveDialog=(AlertDialog)field(settings[0],"dialog");Spinner saveRate=(Spinner)field(settings[0],"rate");runOnMainSync(()->{saveRate.setSelection(3);saveDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});check(Store.prefs(getTargetContext()).getInt("speechRate",2)==3,"speech rate persists after save");
    }
    private Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
    private int intField(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.getInt(target);}
}
